  // Provide the React context that will expose the store to the component tree
  context: MyAppContext,
  // Expose custom hooks for selecting state and dispatching actions
  hooks: {
    useSelector: useStateSelectorHook,
    useDispatch: useDispatchActionHook
  },
  // Apply additional enhancers – here we add another middleware named “myMiddleWare”
  enhancers: [applyMiddleware('myMiddleWare')]
});
```

